(root) => {
    const b = root.querySelector('.n b');
    const chip = root.querySelector('.chip');
    const td = root.querySelector('.td');
    const base = 1284;
    let n = base, i = 0;
    const steps = [2, 1, 3, 1, 2, 1];
    td.style.transform = 'scaleY(.5)';
    const tick = () => {
      if (!root.isConnected) return;
      if (!root.dataset.paused) {
